use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn main() {
    let c = Arc::new(AtomicUsize::new(0));
    let semaphore = Semaphore::new(2);

    let c1 = Arc::clone(&c);
    let semaphore1 = Arc::clone(&semaphore);
