use concir_sync::Semaphore;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Cv {
    w1: Condvar,
    w2: Condvar,
    announced: Condvar,
}

struct Shared {
    m1: Mutex<bool>,
    m2: Mutex<bool>,
    cv: Cv,
    ready: Arc<Semaphore>,
    announced: Mutex<usize>,
}

fn w1(shared: Arc<Shared>) {
    let _permit = shared.ready.acquire();

    let mut announced = shared.announced.lock().unwrap();
    let mut guard = shared.m1.lock().unwrap();
    *announced += 1;
    shared.cv.announced.notify_one();
    drop(announced);

    while !*guard {
        guard = shared.cv.w1.wait(guard).unwrap();
    }
}

fn w2(shared: Arc<Shared>) {
    let _permit = shared.ready.acquire();

    let mut announced = shared.announced.lock().unwrap();
    let mut guard = shared.m2.lock().unwrap();
    *announced += 1;
    shared.cv.announced.notify_one();
    drop(announced);

    while !*guard {
        guard = shared.cv.w2.wait(guard).unwrap();
    }
}

fn notifier(shared: Arc<Shared>) {
    let mut announced = shared.announced.lock().unwrap();
    while *announced < 2 {
        announced = shared.cv.announced.wait(announced).unwrap();
    }
    drop(announced);

    {
        let mut guard = shared.m1.lock().unwrap();
        *guard = true;
        shared.cv.w1.notify_one();
    }

    {
        let mut guard = shared.m2.lock().unwrap();
        *guard = true;
        shared.cv.w2.notify_one();
    }
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(false),
        m2: Mutex::new(false),
        cv: Cv {
            w1: Condvar::new(),
            w2: Condvar::new(),
            announced: Condvar::new(),
        },
        ready: Semaphore::new(2),
        announced: Mutex::new(0),
    });

    let s1 = Arc::clone(&shared);
    let t1 = thread::spawn(move || w1(s1));

    let s2 = Arc::clone(&shared);
    let t2 = thread::spawn(move || w2(s2));

    let s3 = Arc::clone(&shared);
    let tn = thread::spawn(move || notifier(s3));

    t1.join().unwrap();
    t2.join().unwrap();
    tn.join().unwrap();

    println!("DONE done=1");
}
